insert into public.issue_types (key, label, description, severity, position) values
  ('wrong_information', 'Wrong information', 'Told the customer something untrue about their order, product or policy.', 'critical', 1),
  ('skipped_procedure', 'Skipped procedure', 'Didn''t follow the brand''s procedure, e.g. order history not checked, return offered before diagnosis.', 'critical', 2),
  ('missed_question', 'Answered a different question', 'The reply is about something other than what the customer asked.', 'major', 3),
  ('wont_resolve', 'Won''t stop them writing in', 'Technically correct, but leaves the customer without a next step.', 'major', 4),
  ('off_brand_tone', 'Wrong tone for the brand', 'Doesn''t sound like this brand: too curt, too chatty, too formal.', 'minor', 5),
  ('too_slow', 'Too slow', 'Sent later than this brand''s customers expect.', 'minor', 6),
  ('too_long', 'Too long', 'Padding around the answer; the useful line is buried.', 'minor', 7);

